import React from 'react';

const QuanLyCanHo = () => {
    const canHo = [
        { so: '101', loai: '2 Phòng ngủ', trangThai: 'Có người' },
        { so: '102', loai: '1 Phòng ngủ', trangThai: 'Trống' },
        { so: '103', loai: 'Studio', trangThai: 'Có người' },
        { so: '104', loai: 'Penthouse', trangThai: 'Trống' },
    ];

    return (
        <div>
            <h2>🏠 Trạng thái căn hộ</h2>
            <div style={styles.grid}>
                {canHo.map((item) => (
                    <div key={item.so} style={{...styles.card, borderTop: `5px solid ${item.trangThai === 'Trống' ? '#ccc' : '#a52a2a'}`}}>
                        <h3>Phòng {item.so}</h3>
                        <p>{item.loai}</p>
                        <p style={{color: item.trangThai === 'Trống' ? '#888' : '#a52a2a', fontWeight: 'bold'}}>{item.trangThai}</p>
                    </div>
                ))}
            </div>
        </div>
    );
};

const styles = {
    grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '20px', marginTop: '20px' },
    card: { backgroundColor: '#fff', padding: '20px', borderRadius: '10px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)', textAlign: 'center' }
};

export default QuanLyCanHo;
